(function () {
  'use strict';
  const D=window.ATLAS_DATA,C=window.AtlasCore,papers=D.papers,byId=Object.fromEntries(papers.map(p=>[p.id,p]));
  const labels={direction:'研究方向',task:'具体任务',paradigm:'模型 / 技术范式',system:'系统形态',contribution:'贡献类型',problem:'核心研究问题',environment:'环境与平台',training:'训练方式',year:'首次公开年份',venue:'会议 / 期刊',resource:'已核实资源'};
  const resources={paper:'论文',code:'代码',project:'项目页',data:'数据',weights:'权重'};
  const columns={year:'首次公开',task:'任务',training:'训练方式',venue:'发表信息',summary:'核心贡献',resources:'资源',status:'内容状态'};
  const icons={search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M7 17 17 7M7 7h10v10',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',nav:'m12 3 8 18-8-4-8 4 8-18z',arm:'M4 20h16M8 20v-6l5-4-3-5M10 5l4-2 3 5-4 2M5 14h6',scene:'m12 2 9 5v10l-9 5-9-5V7l9-5zM3 7l9 5 9-5M12 12v10',book:'M4 3h13a3 3 0 0 1 3 3v15H6a2 2 0 0 1-2-2V3zM4 17h16M8 7h8M8 11h5',link:'m8 12 5-5a4 4 0 0 1 6 6l-3 3M16 12l-5 5a4 4 0 0 1-6-6l3-3',paper:'M6 2h9l4 4v16H6zM14 2v6h5M9 12h7M9 16h7',code:'m8 5-6 7 6 7M16 5l6 7-6 7',compare:'M5 3v18M19 3v18M2 7h6M16 17h6M12 3v18',heart:'M12 21 3 12C-4 3 8-2 12 6c4-8 16-3 9 6l-9 9z'};
  function svg(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.link}"/></svg>`;}
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safe=url=>{try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?E(u.href):'';}catch{return '';}};
  let state=C.decode(location.search),personal={},storageOK=true,listScroll=0,limit=30,mobileOpen=false,toastTimer,searchTimer,benchOnly=false;
  state.compare=[...new Set(state.compare.map(id=>D.redirects[id]||id))].filter(id=>byId[id]);
  try{const raw=JSON.parse(localStorage.getItem('embodied-atlas.personal.v1')||'null');if(raw)personal=C.importPersonal(raw,papers.map(p=>p.id),D.redirects).data;}catch{storageOK=false;}
  const root=document.getElementById('root'),dialog=document.getElementById('utility-dialog');
  function url(route='',s=state){const q=C.encode(s);return (q?'?'+q:'?')+'#/'+route;}
  function sync(){history.replaceState(null,'',url(location.hash.replace(/^#\//,'')));}
  function notify(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3400);}
  function save(){try{localStorage.setItem('embodied-atlas.personal.v1',JSON.stringify({schemaVersion:1,papers:personal}));storageOK=true;}catch{storageOK=false;notify('浏览器无法持久保存；本次状态仍可用，请导出备份。');}}
  function update(next,reset=true){state={...state,...next};if(reset)limit=30;sync();render();}
  function toggleFilter(dim,value){const set=new Set(state.filters[dim]||[]);set.has(value)?set.delete(value):set.add(value);update({filters:{...state.filters,[dim]:[...set]}});}
  function clearFilters(){update({q:'',filters:{},from:'',to:'',status:'all',library:'all'});}
  function navigate(route){location.href=url(route);}
  function statusBadge(p){const level=p.verificationLevel;const label=level==='fulltext'?'已回查原文':level==='metadata'?'基础来源已核验':level==='unresolved'?'身份 / 来源待核实':p.status==='重点详解'?'核心信息已核验':'待原文核实';return `<span class="status-dot ${level==='fulltext'||level==='metadata'?'verified':''}">${label}</span>`;}

  function venue(p){return p.venue?`${p.venue} ${p.publicationYear||''}`:p.publicationStatus||'发表状态未核实';}
  function resourceLinks(p,max=5){return Object.entries(p.resources).filter(([,r])=>r.url).slice(0,max).map(([k,r])=>`<a class="resource-link" href="${safe(r.url)}" target="_blank" rel="noopener noreferrer" title="${E(r.note||r.status)}">${svg(k==='code'?'code':k==='paper'?'paper':'arrow')}${resources[k]||E(k)}${/404|暂不可用|当前不可用/.test(r.status)?' · 入口失效':r.status!=='已核实入口'?' ?':''}</a>`).join('');}
  function paperTags(p,max=5){let ts=[];for(const d of ['direction','task','paradigm','contribution'])for(const v of p.tags[d])ts.push({d,v});return ts.slice(0,max).map(({d,v},i)=>`<button class="tag ${i===0?'accent':''}" data-filter="${d}" data-value="${E(v)}" title="筛选${labels[d]}：${E(v)}">${E(v)}</button>`).join('');}
  function readSelect(p){const v=personal[p.id]?.read||'none';return `<select data-read="${p.id}" aria-label="${E(p.short)}的阅读状态" class="read-select"><option value="none" ${v==='none'?'selected':''}>阅读状态</option><option value="unread" ${v==='unread'?'selected':''}>待读</option><option value="read" ${v==='read'?'selected':''}>已读</option></select>`;}
  function card(p){const u=personal[p.id]||{},minimal=state.density==='minimal';return `<article class="paper-card"><div class="paper-top"><span class="paper-year">${p.firstPublished?E(p.firstPublished.slice(0,4)):'日期未核实'}${p.venue?' · '+E(p.venue):''}</span>${statusBadge(p)}</div><h3><a href="${E(url('paper/'+p.id))}" data-paper="${p.id}">${E(p.title)}</a></h3><div class="tags">${paperTags(p,minimal?3:5)}</div>${minimal?'':`<p class="paper-summary">${E(p.summary)}</p><p class="paper-meta">${E(venue(p))}</p>`}${state.density==='detailed'?`<div class="detail-excerpt"><p><b>方法</b> ${E(p.method?.flow?.join(' → ')||'未核实')}</p><p><b>训练</b> ${E(p.training?.regime||'未核实')}</p><p><b>评测</b> ${E(p.evaluation.map(x=>x.benchmark).join('；')||'未核实')}</p><p><b>边界分析</b> ${E(p.limitations.analysis[0]||'待原文核实后分析')}</p></div>`:''}<div class="card-foot">${minimal?'':resourceLinks(p,2)}<div class="card-actions"><button data-star="${p.id}" class="${u.starred?'on':''}" aria-label="${u.starred?'取消收藏':'收藏'} ${E(p.short)}" aria-pressed="${!!u.starred}" title="${u.starred?'已收藏':'收藏'}">${u.starred?'★':'☆'}</button>${readSelect(p)}<label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${state.compare.includes(p.id)?'checked':''} aria-label="对比 ${E(p.short)}">对比</label></div></div></article>`;}
  function facet(dim,open){const cs=C.counts(papers,state,personal,dim);const selected=state.filters[dim]||[];const vals=[...new Set([...Object.keys(cs),...selected])].sort((a,b)=>dim==='year'?b.localeCompare(a):((D.taxonomy[dim]||[]).indexOf(a)-(D.taxonomy[dim]||[]).indexOf(b))||a.localeCompare(b,'zh'));if(!vals.length)return '';return `<details class="facet" data-facet="${dim}" ${open?'open':''}><summary>${labels[dim]}${selected.length?' · '+selected.length:''}</summary><div class="facet-body">${vals.map(v=>`<label class="filter-option ${selected.includes(v)?'selected':''}"><input type="checkbox" data-facet-check="${dim}" value="${E(v)}" ${selected.includes(v)?'checked':''}><span>${E(v)}</span><small>${cs[v]||0}</small></label>`).join('')}</div></details>`;}
  let openFacets=new Set(['task','contribution','environment']);
  function sidebar(){return `<aside class="sidebar ${mobileOpen?'open':''}" id="filters" aria-label="多维论文筛选"><div class="filter-heading"><b>筛选论文</b><button class="text-button" data-action="clear">重置筛选</button></div><p class="filter-logic">同维度 OR · 跨维度 AND</p>${['task','contribution','environment','paradigm','problem','training','system','direction','year','venue','resource'].map(d=>facet(d,openFacets.has(d))).join('')}<details class="facet" open><summary>首次公开日期</summary><div class="facet-body date-fields"><label>起始日期<input type="date" id="date-from" value="${E(state.from)}" aria-label="首次公开起始日期"></label><label>截止日期<input type="date" id="date-to" value="${E(state.to)}" aria-label="首次公开截止日期"></label></div></details><p class="side-note">数量已考虑其他维度的条件。当前维度的各选项可相互组合。日期未知的条目仍在“全部论文”中。</p></aside>`;}
  const segment=(key,opts)=>`<div class="segmented" role="group" aria-label="${key==='view'?'布局':'信息密度'}">${opts.map(([v,l])=>`<button data-setting="${key}" data-value="${v}" class="${state[key]===v?'active':''}" aria-pressed="${state[key]===v}">${l}</button>`).join('')}</div>`;
  function toolbar(n){return `<div class="toolbar"><div class="result-count"><b>${n}</b><span>篇论文</span><small>去重统计</small></div><button class="mobile-filter" data-action="mobile" aria-expanded="${mobileOpen}" aria-controls="filters">☷ 筛选</button><div class="toolbar-controls"><label>排序<select id="sort">${[['curated','重点阅读优先'],['date-desc','首次公开 · 从新到旧'],['date-asc','首次公开 · 从旧到新'],['title','标题 · A–Z']].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${l}</option>`).join('')}</select></label>${segment('view',[['cards','卡片'],['table','表格']])}</div></div><div class="toolbar-second"><div><label>分组 <select id="group">${[['none','不分组'],...Object.entries(labels).filter(([k])=>k!=='resource')].map(([v,l])=>`<option value="${v}" ${state.group===v?'selected':''}>${l}</option>`).join('')}</select></label><label><span class="sr-label">资料状态</span><select id="status" aria-label="资料状态">${[['all','全部论文'],['deep','重点详解'],['pending','待核实 / 待完善'],['fulltext','已回查原文'],['metadata','仅基础核验'],['unresolved','身份待核实'],['numbers','含量化数据']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div>${segment('density',[['minimal','极简'],['standard','标准'],['detailed','详细']])}${state.view==='table'?'<button class="button-small" data-action="columns">显示列</button>':''}</div></div>`;}
  function chips(){const list=[];for(const [d,vs] of Object.entries(state.filters))for(const v of vs)list.push(`<button class="chip-remove" data-filter="${d}" data-value="${E(v)}">${labels[d]}：${E(v)} <b>×</b></button>`);if(state.q)list.push(`<button class="chip-remove" data-remove="q">搜索：${E(state.q)} <b>×</b></button>`);for(const [k,l] of [['from','起始'],['to','截止']])if(state[k])list.push(`<button class="chip-remove" data-remove="${k}">${l}：${E(state[k])} <b>×</b></button>`);if(state.library!=='all')list.push(`<button class="chip-remove" data-remove="library">${({starred:'我的收藏',unread:'待读',read:'已读'})[state.library]} <b>×</b></button>`);if(state.status!=='all')list.push(`<button class="chip-remove" data-remove="status">${({deep:'重点详解',pending:'待核实 / 待完善',fulltext:'已回查原文',metadata:'仅基础核验',unresolved:'身份待核实',numbers:'含量化数据'})[state.status]||'资料状态'} <b>×</b></button>`);return `<div class="active-filters">${list.join('')}${list.length?'<button class="text-button" data-action="clear">清空全部</button>':''}</div>`;}
  function tableCell(p,key){switch(key){case 'year':return E(p.firstPublished||'未核实');case 'venue':return E(venue(p));case 'task':return p.tags.task.map(t=>`<span class="tag">${E(t)}</span>`).join(' ');case 'training':return E(p.training?.regime||'未核实');case 'summary':return E(p.summary);case 'resources':return resourceLinks(p);case 'status':return statusBadge(p);default:return '';}}
  function table(ps){return `<div class="table-wrap" tabindex="0" role="region" aria-label="论文比较表，可横向滚动"><table class="paper-table"><thead><tr><th scope="col">选择</th><th scope="col"><button data-table-sort="title" title="按标题排序">论文标题 ↕</button></th>${state.columns.map(c=>`<th scope="col">${c==='year'?'<button data-table-sort="date-desc" title="切换首次公开时间排序">首次公开 ↕</button>':columns[c]}</th>`).join('')}</tr></thead><tbody>${ps.map(p=>`<tr><td class="select-cell"><input type="checkbox" data-compare="${p.id}" ${state.compare.includes(p.id)?'checked':''} aria-label="对比 ${E(p.short)}"></td><td class="title-cell"><a class="table-title" href="${E(url('paper/'+p.id))}" data-paper="${p.id}">${E(p.title)}</a>${state.density==='minimal'?'':`<p class="table-summary">${E(p.summary)}</p><div class="tags">${paperTags(p,3)}</div>`}${state.density==='detailed'?`<p class="table-summary">方法：${E(p.method?.flow?.join(' → ')||'未核实')}<br>评测：${E(p.evaluation.map(x=>x.benchmark).join('；')||'未核实')}<br>局限分析：${E(p.limitations.analysis[0]||'未核实')}</p>`:''}<div class="table-personal"><button class="text-button" data-star="${p.id}" aria-label="收藏 ${E(p.short)}" aria-pressed="${!!personal[p.id]?.starred}">${personal[p.id]?.starred?'★ 已收藏':'☆ 收藏'}</button>${readSelect(p)}</div></td>${state.columns.map(c=>`<td>${tableCell(p,c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
  function renderList(){const ps=C.results(papers,state,personal),deep=papers.filter(p=>p.status==='重点详解').length;const cats=['导航','操作','移动操作','综合具身智能','场景表征','具身医疗'];const cg=C.counts(papers,state,personal,'direction');let note='';const selected=(state.filters.direction||[]);if(selected.length===1&&D.categories[selected[0]]){const info=D.categories[selected[0]];note=`<div class="context-note"><strong>${E(selected[0])}</strong> ${E(info)}</div>`;}if(state.group!=='none')note+=`<p class="small-print">按「${labels[state.group]}」分组；多标签论文可能出现在多个组，顶部总数按唯一 ID 去重。</p>`;if(state.from&&state.to&&state.from>state.to)note+='<p class="notice">起始日期晚于截止日期，请调整日期范围。</p>';if(state.from||state.to)note+='<p class="small-print">时间范围仅匹配已核实的首次公开日期；日期未知的论文可在清除日期后找到。</p>';let shown=ps.slice(0,limit),grouped=C.groups(shown,state.group);root.innerHTML=`<main class="page" id="main"><section class="intro"><div><p class="eyebrow">AN OPEN MAP OF EMBODIED INTELLIGENCE</p><h1>从论文，到研究<em>脉络。</em></h1><p>发现相关工作，读懂方法差异，为下一步研究找到坐标。</p></div><div class="stats"><div><b>${papers.length}</b><small>篇基础索引</small></div><div><b>${deep}</b><small>篇重点详解</small></div><div><b>${D.audit?.numericEvidence||0}</b><small>篇原文数据表</small></div></div></section><div class="search-wrap"><label class="searchbox">${svg('search')}<input type="search" id="search" placeholder="搜索论文、作者、研究问题… 支持中英文" value="${E(state.q)}" aria-label="全局论文搜索"><span class="keyhint">/</span></label><button class="primary" data-action="share-list">复制筛选链接 ${svg('arrow')}</button></div><section class="category-strip" aria-label="按研究方向筛选">${cats.map((cat,i)=>`<button class="category-tile ${(state.filters.direction||[]).includes(cat)?'active':''}" data-filter="direction" data-value="${cat}" aria-pressed="${(state.filters.direction||[]).includes(cat)}">${svg(['nav','arm','scene','grid','scene','heart'][i])}<span class="tile-name">${cat}</span><span>${cg[cat]||0}</span></button>`).join('')}</section><div class="workspace">${sidebar()}<section class="result-area ${state.density}" aria-label="论文结果">${toolbar(ps.length)}${chips()}<div class="verification-summary"><span>回查原文 ${D.audit?.fulltext||0}</span><span>基础核验 ${D.audit?.metadata||0}</span><span>身份或来源待确认 ${D.audit?.unresolved||0}</span></div>${note}${ps.length?grouped.map(([name,list])=>`${state.group!=='none'?`<div class="section-title"><h2>${E(name)}</h2><small>${list.length} 篇（当前批次）</small></div>`:'<div class="section-title"><h2>探索论文</h2><small>先建立全貌，再深入阅读</small></div>'}${state.view==='table'?table(list):`<div class="paper-grid">${list.map(card).join('')}</div>`}`).join(''):`<div class="empty"><div class="empty-icon">∅</div><h3>暂时没有匹配的论文</h3><p>可以放宽日期范围、移除部分标签，或查看全部基础索引。</p><button data-action="clear">清空筛选，浏览全部</button></div>`}${ps.length>limit?`<button class="load-more" data-action="more">继续显示 ${Math.min(30,ps.length-limit)} 篇 · 共 ${ps.length} 篇</button>`:''}<p class="small-print result-note" role="status">${ps.length?`已显示 ${Math.min(limit,ps.length)} / ${ps.length} 篇。`:''}“?” 表示资源尚未核实；条目与事实的核验状态请以详情页为准。</p></section></div></main>`;renderTray();}
  function renderTray(){document.querySelector('.compare-tray')?.remove();if(!state.compare.length||!['','/'].includes(routeName()))return;const el=document.createElement('aside');el.className='compare-tray';el.setAttribute('aria-label','已选择的对比论文');el.innerHTML=`<div><b>${state.compare.length} / 4</b><br><small>篇待对比</small></div><div class="compare-items">${state.compare.map(id=>`<button class="compare-pill" data-toggle-compare="${id}" title="移除 ${E(byId[id].short)}">${E(byId[id].short)} ×</button>`).join('')}</div><button class="text-button" data-action="clear-compare">清空</button><button class="primary" data-action="compare" ${state.compare.length<2?'disabled':''}>开始对比 →</button>`;document.body.append(el);}
  function toggleCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else{if(state.compare.length>=4){notify('最多可选择4篇论文，请先移除一篇。');render();return;}state.compare.push(id);}sync();render();}
  function fields(obj,map){return `<dl class="definition-grid">${Object.entries(map).map(([k,l])=>`<div ${['data','stages','objective','assumptions','difference','collection','split','leakage','assets'].includes(k)?'class="wide"':''}><dt>${l}</dt><dd>${E(obj?.[k]||'未核实')}</dd></div>`).join('')}</dl>`;}
  const benchmarkFields={motivation:'新增价值',task:'任务定义',input:'输入',output:'输出',actions:'动作空间',success:'成功判据',collection:'采集、生成与质量控制',environment:'环境与平台',scale:'规模与统计口径',split:'训练 / 验证 / 测试划分',metrics:'指标与协议',baselines:'基线',assets:'开放资源与场景资产',license:'许可证',reproduction:'复现门槛',coverage:'覆盖能力',boundary:'评测边界',leakage:'泄漏与潜在偏差'};
  function section(id,n,title,content){return `<section class="detail-section" id="${id}"><h2><span>${n}</span>${title}</h2>${content}</section>`;}
  function renderDetail(id,anchor){id=D.redirects[id]||id;const p=byId[id];if(!p){root.innerHTML=`<main class="page" id="main"><div class="empty"><h1>没有找到这篇论文</h1><p>记录可能已更新。请返回论文库检索标题。</p><a class="back-link" href="${E(url())}">← 返回论文库</a></div></main>`;return;}
    document.title=p.short+' · Embodied Atlas';const isBenchmark=p.tags.contribution.some(x=>['Benchmark','数据集'].includes(x));const sections=[['overview','快速理解'],['method','方法解析'],['training','模型与训练'],...(isBenchmark?[['benchmark','Benchmark 协议']]:[]),['evidence','实验与证据'],['reproduction','复现详情'],['limits','局限与分析'],['related','关联阅读'],['sources','来源与核验']];
    const related=p.related?.length?p.related:papers.filter(x=>x.id!==p.id&&x.status==='重点详解'&&x.tags.direction.some(t=>p.tags.direction.includes(t))).slice(0,3).map(x=>({id:x.id,reason:'共享研究方向；由本库标签匹配，非论文作者推荐。'}));
    root.innerHTML=`<main class="page" id="main"><div class="breadcrumb"><a class="back-link" href="${E(url())}" data-back>← 返回论文库</a><span>/</span><span>${E(p.tags.direction.join(' · ')||'待分类')}</span><span>/</span><span>${E(p.short)}</span></div><header class="detail-header"><div class="paper-top"><span class="eyebrow">PAPER NOTES / ${E(p.firstPublished||'首次公开日期未核实')}</span>${statusBadge(p)}</div><h1>${E(p.title)}</h1><p class="authors">${p.authors.length?E(p.authors.join(' · ')):'作者列表未核实'}<br>${p.institutions.length?E(p.institutions.join(' · ')):'作者机构未核实'}</p><div class="tags">${paperTags(p,12)}</div><div class="detail-tools">${resourceLinks(p)}<button data-action="share-paper">复制详情链接</button><button data-bibtex="${p.id}" ${p.bibtex?'':'disabled'} title="${p.bibtex?'基于已核实书目信息':'尚无完整、已核实 BibTeX'}">复制 BibTeX</button><button data-star="${p.id}" aria-pressed="${!!personal[p.id]?.starred}">${personal[p.id]?.starred?'★ 已收藏':'☆ 收藏'}</button>${readSelect(p)}</div>${!Object.keys(p.resources).length?'<p class="provenance-warning">尚无已确认资源入口。请查看来源中的用户清单线索。</p>':''}</header><div class="detail-layout"><nav class="toc" aria-label="论文详情目录"><p>ON THIS PAGE</p>${sections.map(([a,l],i)=>`<a href="${E(url('paper/'+p.id+'/'+a))}" data-section="${a}">${String(i+1).padStart(2,'0')}　${l}</a>`).join('')}</nav><article class="detail-body">${section('overview','01','快速理解',`<div class="overview-box"><p class="eyebrow">THE ESSENTIAL IDEA</p><p>${E(p.overview||p.summary)}</p></div>${p.status==='待核实'?'<p class="notice">本条尚未回到原文核实。下列空白明确保留；用户调研摘记可在来源区展开。</p>':''}${fields(p,{firstPublished:'首次公开日期',updated:'最新版本日期',publicationYear:'正式发表年份',publicationStatus:'发表状态',venue:'会议 / 期刊',checked:'最近核验日期'})}`)}${section('method','02','方法解析',window.AtlasDetail.method(p))}${section('training','03','模型与训练',fields(p.training,{regime:'训练性质',models:'基础模型及角色',trainable:'训练 / 优化部分',frozen:'冻结部分',data:'数据与监督',objective:'训练目标',stages:'训练与推理阶段'}))}${isBenchmark?section('benchmark','04','Benchmark / 数据集协议',p.benchmark?fields(p.benchmark,benchmarkFields):'<p class="notice">此条有 Benchmark / 数据集贡献，专属任务、划分、指标和许可仍待原文逐项核验。</p>'):''}${section('evidence',isBenchmark?'05':'04','实验与证据',window.AtlasDetail.evidence(p))}${section('reproduction',isBenchmark?'06':'05','复现详情',window.AtlasDetail.reproduction(p))}${section('limits',isBenchmark?'07':'06','局限与后续问题',`<div class="limit-grid"><div><h3>论文自述的局限</h3>${p.limitations.author.length?p.limitations.author.map(l=>`<p>${E(l)}</p>`).join(''):'<p class="muted">尚未摘录已核实的自述局限；不代表论文没有局限。</p>'}</div><div><h3>本库基于证据的分析</h3>${p.limitations.analysis.length?p.limitations.analysis.map(l=>`<p>${E(l)}</p>`).join(''):'<p class="muted">待原文核实后补充。</p>'}</div></div>`)}${section('related',isBenchmark?'08':'07','关联阅读',related.length?`<div class="related-grid">${related.filter(r=>byId[r.id]).map(r=>`<a class="related-item" href="${E(url('paper/'+r.id))}" data-paper="${r.id}"><b>${E(byId[r.id].short)} ↗</b><p>${E(r.reason)}</p></a>`).join('')}</div>`:'<p class="muted">尚无已确认的关联阅读。</p>')}${section('sources',isBenchmark?'09':'08','来源与核验',`<p class="small-print">“核心信息已核验”只覆盖下列注明的事实范围。未回查的出版、训练和资源信息继续保留为待核实。</p><ul class="source-list">${p.sources.map(s=>`<li><span class="source-kind ${s.kind==='primary'?'':'user'}">${s.kind==='primary'?'原始来源':s.kind==='user'?'用户资料':'待回查线索'}</span>${s.url?`<a href="${safe(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.label)} ↗</a>`:E(s.label)}<small>${E(s.locator||'')}　·　支持：${E((s.supports||[]).join('、'))}</small></li>`).join('')}</ul><h3>待补全项</h3><p class="gaps">${E(p.gaps?.join('；')||'当前无登记缺口')}</p><h3>资源状态</h3><p class="gaps">${Object.entries(resources).map(([k,l])=>`${l}：${E(p.resources[k]?.status||'未核实')}`).join('　/　')}</p>${p.sourceNotes?.length?`<details class="source-notes"><summary>查看原始调研摘记（未回查，不作为已核实事实）</summary><pre>${E(JSON.stringify(p.sourceNotes,null,2))}</pre></details>`:''}${p.citationNote?`<p class="small-print">${E(p.citationNote)}</p>`:''}${!p.bibtex?'<p class="small-print">完整 BibTeX 尚未核实，复制引用暂不可用。</p>':''}`)}</article></div></main>`;
    if(anchor)setTimeout(()=>document.getElementById(anchor)?.scrollIntoView(),0);
  }
  function renderCompare(){const ps=state.compare.map(id=>byId[id]).filter(Boolean);document.title='论文对比 · Embodied Atlas';if(ps.length<2){root.innerHTML=`<main class="page" id="main"><div class="empty"><h1>请选择 2–4 篇论文</h1><p>返回论文库，勾选“对比”后再开始。</p><a href="${E(url())}" class="back-link">← 返回论文库</a></div></main>`;return;}const hasBench=ps.some(p=>p.tags.contribution.some(x=>['Benchmark','数据集'].includes(x)));const rows=benchOnly&&hasBench?Object.entries(benchmarkFields).map(([k,l])=>[l,p=>p.benchmark?.[k]||'未核实 / 不适用：该条未整理专属协议']):[
    ['研究问题',p=>p.overview||p.summary],['方法流程',p=>p.method?.flow?.join(' → ')||'未核实'],['输入与输出',p=>p.method?`${p.method.input} → ${p.method.output}`:'未核实'],['适用前提',p=>p.method?.assumptions||'未核实'],['训练性质',p=>p.training?.regime||'未核实'],['训练与冻结',p=>p.training?`训练：${p.training.trainable}；冻结：${p.training.frozen}`:'未核实'],['训练数据与目标',p=>p.training?`${p.training.data}；${p.training.objective}`:'未核实'],['评测与协议',p=>p.evaluation.map(x=>`${x.benchmark}：${x.setting}`).join('\n\n')||'未核实'],['作者报告',p=>p.evaluation.map(x=>x.result).join('\n\n')||'未核实'],['关键数值（保持原协议）',p=>p.evaluation.flatMap(e=>{const ts=[e.table,...(e.tables||[])].filter(Boolean);return ts.map(t=>`${e.benchmark} / ${e.setting}：${t.columns.join(' | ')}；${t.rows.slice(0,4).map(r=>(Array.isArray(r)?r:Object.values(r)).join(' | ')).join('；')}`);}).join('\n\n')||'原文量化数据尚未填入'],['复现状态',p=>p.reproduction?.status||'未复现'],['论文自述局限',p=>p.limitations.author.join('；')||'未摘录已核实内容'],['本库分析',p=>p.limitations.analysis.join('；')||'未核实'],['发表信息',p=>`${venue(p)}；首次公开：${p.firstPublished||'未核实'}；最新版本：${p.updated||'未核实'}`],['核验状态',p=>`${p.status}；核验：${p.checked||'尚未核验'}；缺口：${p.gaps?.join('、')||'无'}`]];
    root.innerHTML=`<main class="page compare-page" id="main"><div class="breadcrumb"><a href="${E(url())}" class="back-link" data-back>← 返回论文库</a><span>/</span><span>并排对比</span></div><div class="article-intro"><p class="eyebrow">COMPARE WITH CONTEXT</p><h1>读懂差异，再做选择。</h1><p>正在比较 ${ps.length} 篇论文。逐行查看假设、训练与证据；本页不计算统一分数。</p></div><div class="compare-toolbar">${hasBench?`<label><input type="checkbox" id="benchmark-only" ${benchOnly?'checked':''}>使用 Benchmark / 数据集专属比较字段</label>`:''}<button class="button-small" data-action="share-compare">复制对比链接</button></div><div class="notice">各论文的资源、模型、数据划分和评测预算可能不同。缺失信息明确保留为“未核实”，避免把未报告写成没有。</div><br><div class="compare-scroll" role="region" tabindex="0" aria-label="论文并排对比，可横向滚动"><table class="compare-table" style="min-width:${150+ps.length*280}px"><thead><tr><th scope="col">${benchOnly?'Benchmark 协议':'研究与方法'}</th>${ps.map(p=>`<td><a href="${E(url('paper/'+p.id))}" data-paper="${p.id}">${E(p.short)} ↗</a><p class="cell-note">${E(p.title)}</p><button class="text-button" data-remove-compare="${p.id}">移出对比 ×</button></td>`).join('')}</tr></thead><tbody>${rows.map(([l,fn])=>`<tr><th scope="row">${l}</th>${ps.map(p=>`<td>${E(fn(p)).replace(/\n/g,'<br>')}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">资源入口</th>${ps.map(p=>`<td>${resourceLinks(p)||'未核实'}</td>`).join('')}</tr></tbody></table></div></main>`;
  }
  function routeName(){return location.hash.replace(/^#\//,'').split('/')[0];}
  function renderRoutes(){document.title='入门阅读路线 · Embodied Atlas';root.innerHTML=`<main class="page article-page" id="main"><div class="article-intro"><p class="eyebrow">READING PATHS / START SMALL</p><h1>先理解问题，再深入方法。</h1><p>四条小而清晰的阅读路线。推荐理由由本库整理；不表示论文优劣，也不替代对原文的判断。</p></div><div class="route-grid">${D.routes.map((r,i)=>`<section class="route-card"><span class="route-number">0${i+1}</span><h2>${E(r.title)}</h2><p>${E(r.description)}</p>${r.papers.map(s=>byId[s.id]?`<a href="${E(url('paper/'+s.id))}" data-paper="${s.id}" class="route-item"><b>${E(byId[s.id].short)} ↗</b><small>${E(s.reason)}</small></a>`:'').join('')}</section>`).join('')}</div></main>`;}
  function renderAbout(){document.title='资料与方法 · Embodied Atlas';const deep=papers.filter(p=>p.status==='重点详解').length;root.innerHTML=`<main class="page article-page" id="main"><div class="article-intro"><p class="eyebrow">SOURCES, SCOPE & EDITORIAL NOTES</p><h1>把确定的事实与未知分开。</h1><p>从16份用户资料与本轮补充线索出发，整理 ${papers.length} 条唯一索引、${deep} 篇重点详解；其中 ${D.audit?.fulltext||0} 篇已回查原文、${D.audit?.metadata||0} 篇完成基础核验、${D.audit?.numericEvidence||0} 篇整理了原文量化表格。资料覆盖导航、操作、Agent、巡检、3D/4D 重建及具身医疗；其中也保留少量非实体行动的相关支撑工作。</p></div><section class="about-section"><h2>怎样阅读核验状态</h2><table><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>已回查原文</td><td>已取得并回查论文全文，整理方法与原文可核实的数据。量化表格逐一注明版本与条件，不代表研究代码已经复现。</td></tr><tr><td>基础来源已核验</td><td>已确认论文身份与可取得的元数据；无法获取全文时明确保留方法、实验等缺口，不用摘要推测图表结果。</td></tr><tr><td>基础索引 / 待原文核实</td><td>来自用户清单和摘记，尚未提升为原文事实。原始摘记保留在详情来源区，避免假装已读完全部论文。</td></tr><tr><td>资源入口已核实</td><td>已在原始来源确认入口，不等于实际下载、运行过代码或验证许可证。</td></tr></tbody></table></section><section class="about-section"><h2>分类与筛选</h2><p>研究方向、任务、技术、系统、贡献与环境分别建模。同维度多选为 OR，不同维度为 AND。标签数量考虑其他筛选维度，在本维度中保留可组合项。多标签分组允许重复出现，总数按稳定 ID 去重。</p><p>真实采集资产、真实世界实验、仿真评测和预采集证据池分开标注。首次公开、最新版本和正式发表年份是三个不同字段；日期筛选只使用已核实的首次公开日期。</p></section><section class="about-section"><h2>本轮发现的内容风险</h2><ul><li>已删除首次导入中误识别的三个调研讨论标题，相关记录不再计入论文总数。</li><li>两篇 4DGS 分别采用规范空间形变与原生四维分布，不能按简称合并。</li><li>RoboHarness 与 AgenticNav 存在同名不同工作；分别建立记录并说明身份。</li><li>OpenEQA EM、Active、题目子集与各方法的 judge 配置不同，原表分数未自动做排行榜。</li><li>ETA 的当前候选更新未通过全部验证闸门；本库不将其写为已获得稳定自进化增益。</li><li>RoboHarness 策略编排 v3 扩大了公开基准范围；旧笔记中的实验规模保留为版本差异。</li></ul></section><section class="about-section"><h2>本地阅读记录</h2><p>收藏、待读与已读仅保存在当前浏览器的当前站点存储中，不会自动跨设备、跨域名同步。隐私模式、清理浏览器或迁移网址可能使记录不可用。使用导出/导入进行备份；导入只接受已知论文 ID 并检查字段，合并时文件中的同 ID 状态覆盖本地值。</p><button data-action="library">管理与备份阅读记录</button></section><section class="about-section"><h2>给维护者</h2><p>每条论文对应一个 JSON 文件；新增内容后运行数据校验与静态构建即可。项目附有 README、字段定义、来源盘点、待核实清单和 GitHub Pages Actions 工作流。页面不含 API 密钥，所有浏览与交互均在本地完成。</p><button data-action="export-catalog">导出当前论文数据 JSON</button> <button data-action="pending">查看待完善条目</button></section><section class="about-section"><h2>核验边界</h2><p>本轮主要核验原文和官方入口，未下载并运行所有研究代码、模型或数据；也没有把“来源访问失败”解释成“资源不存在”。纸面描述、作者报告结果与本库分析分别展示。关联推荐来自明确关系或共享标签，均注明原因。</p></section></main>`;}
  function render(){benchOnly=state.compareMode==='benchmark';const focus=document.activeElement?.id,selection=document.activeElement?.selectionStart;const hash=location.hash.replace(/^#\//,'');const [page,id,anchor]=hash.split('/');document.querySelector('.compare-tray')?.remove();document.title='Embodied Atlas · 具身智能论文知识库';if(page==='paper')renderDetail(id,anchor);else if(page==='compare')renderCompare();else if(page==='routes')renderRoutes();else if(page==='about')renderAbout();else renderList();for(const el of document.querySelectorAll('[data-nav]'))el.classList.toggle('active',el.dataset.nav===(page==='routes'?'routes':page==='about'?'about':'papers'));if(focus){const el=document.getElementById(focus);if(el){el.focus({preventScroll:true});if(typeof selection==='number'&&el.type==='search')el.setSelectionRange(selection,selection);}}}
  function openDialog(title,html){document.getElementById('utility-title').textContent=title;document.getElementById('utility-content').innerHTML=html;if(!dialog.open)dialog.showModal();}
  function showLibrary(){const us=Object.values(personal);openDialog('我的阅读记录',`<p class="dialog-note">保存在当前浏览器，不会自动跨设备同步。${!storageOK?'当前存储不可用，请及时导出。':''}</p><div class="library-grid">${[['starred','收藏',us.filter(x=>x.starred).length],['unread','待读',us.filter(x=>x.read==='unread').length],['read','已读',us.filter(x=>x.read==='read').length]].map(([v,l,n])=>`<button data-library-filter="${v}"><b>${n}</b><small>${l} →</small></button>`).join('')}</div><p class="dialog-note">导入将合并记录；文件中的同名论文状态覆盖本地。未知 ID 会跳过。</p><div class="dialog-actions"><button class="primary" data-action="export-personal">导出阅读记录</button><button data-action="import-personal">导入 JSON</button><button data-action="export-catalog">导出论文数据</button></div>`);}
  async function copy(text){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();if(!ok)throw Error('copy');}notify('已复制到剪贴板');}catch{openDialog('手动复制',`<p class="dialog-note">浏览器暂不允许自动复制，请选中下方内容复制。</p><textarea class="dialog-input" rows="7" readonly aria-label="可手动复制的内容">${E(text)}</textarea>`);document.querySelector('#utility-content textarea').select();}}
  function share(){const current=new URL(location.href);current.search=C.encode(state);copy(current.href);}
  function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('导出文件已生成');}
  document.addEventListener('click',e=>{
    const el=e.target.closest('button,a,[data-close]');if(!el)return;
    if(el.hasAttribute('data-close')){dialog.close();return;}
    if(el.dataset.section){e.preventDefault();document.getElementById(el.dataset.section)?.scrollIntoView({behavior:'smooth'});history.replaceState(null,'',url('paper/'+(location.hash.split('/')[2]||'')+'/'+el.dataset.section));return;}
    if(el.classList.contains('skip')){e.preventDefault();const m=document.getElementById('main');m?.setAttribute('tabindex','-1');m?.focus();return;}
    if(el.dataset.paper){if(!routeName())listScroll=window.scrollY;return;}
    if(el.hasAttribute('data-back')){e.preventDefault();navigate('');setTimeout(()=>window.scrollTo(0,listScroll),30);return;}
    if(el.dataset.filter){if(routeName()){state.filters={...state.filters,[el.dataset.filter]:[el.dataset.value]};sync();navigate('');}else toggleFilter(el.dataset.filter,el.dataset.value);return;}
    if(el.dataset.remove){const key=el.dataset.remove;update({[key]:C.defaults[key]});return;}
    if(el.dataset.setting){update({[el.dataset.setting]:el.dataset.value},false);return;}
    if(el.dataset.star){const id=el.dataset.star;personal[id]={...personal[id],starred:!personal[id]?.starred};save();render();notify(personal[id].starred?'已收藏':'已取消收藏');return;}
    if(el.dataset.toggleCompare){toggleCompare(el.dataset.toggleCompare);return;}
    if(el.dataset.removeCompare){state.compare=state.compare.filter(id=>id!==el.dataset.removeCompare);sync();render();return;}
    if(el.dataset.libraryFilter){dialog.close();state.library=el.dataset.libraryFilter;sync();navigate('');if(!routeName())render();return;}
    if(el.dataset.bibtex){const p=byId[el.dataset.bibtex];if(p.bibtex)copy(p.bibtex);return;}
    if(el.dataset.tableSort){let sort=el.dataset.tableSort;if(sort==='date-desc'&&state.sort==='date-desc')sort='date-asc';update({sort});return;}
    const action=el.dataset.action;
    if(action==='clear')clearFilters();
    else if(action==='mobile'){mobileOpen=!mobileOpen;render();}
    else if(action==='more'){limit+=30;render();}
    else if(action==='share-list'||action==='share-paper'||action==='share-compare')share();
    else if(action==='clear-compare'){state.compare=[];sync();render();}
    else if(action==='compare'){navigate('compare');}
    else if(action==='library')showLibrary();
    else if(action==='columns')openDialog('表格显示列',`<p class="dialog-note">标题与选择列始终保留，其他列可自由调整。</p><div class="column-options">${Object.entries(columns).map(([k,l])=>`<label class="filter-option"><input type="checkbox" data-column="${k}" ${state.columns.includes(k)?'checked':''}><span>${l}</span></label>`).join('')}</div>`);
    else if(action==='export-personal')download('embodied-atlas-reading.json',{schemaVersion:1,exportedAt:new Date().toISOString(),papers:personal});
    else if(action==='import-personal'){document.getElementById('import-file').value='';document.getElementById('import-file').click();}
    else if(action==='export-catalog')download('embodied-atlas-catalog.json',D);
    else if(action==='pending'){state.status='pending';sync();navigate('');}
  });
  document.addEventListener('change',e=>{const el=e.target;
    if(el.dataset.facetCheck){toggleFilter(el.dataset.facetCheck,el.value);return;}
    if(el.dataset.compare){toggleCompare(el.dataset.compare);return;}
    if(el.dataset.read){personal[el.dataset.read]={...personal[el.dataset.read],read:el.value};save();render();notify('阅读状态已更新');return;}
    if(el.dataset.column){const s=new Set(state.columns);el.checked?s.add(el.dataset.column):s.delete(el.dataset.column);state.columns=Object.keys(columns).filter(k=>s.has(k));sync();render();return;}
    if(['sort','group','status'].includes(el.id)){update({[el.id]:el.value});return;}
    if(el.id==='date-from'||el.id==='date-to'){update({[el.id==='date-from'?'from':'to']:el.value});return;}
    if(el.id==='benchmark-only'){state.compareMode=el.checked?'benchmark':'general';sync();render();}
  });
  document.addEventListener('toggle',e=>{if(e.target.dataset?.facet){const key=e.target.dataset.facet;e.target.open?openFacets.add(key):openFacets.delete(key);}},true);
  document.addEventListener('input',e=>{if(e.target.id==='search'){state.q=e.target.value;sync();limit=30;clearTimeout(searchTimer);searchTimer=setTimeout(()=>render(),160);}});
  document.getElementById('import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw Error('文件过大，请使用本网站导出的阅读记录 JSON。');const parsed=JSON.parse(await file.text());const r=C.importPersonal(parsed,papers.map(p=>p.id),D.redirects);personal={...personal,...r.data};save();render();showLibrary();notify(`已合并 ${Object.keys(r.data).length} 条记录${r.skipped?'，跳过 '+r.skipped+' 个未知 ID':''}`);}catch(err){notify(err.message||'导入失败，原有记录未更改');}});
  document.getElementById('library-btn').addEventListener('click',showLibrary);
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();document.getElementById('search')?.focus();}});
  window.addEventListener('hashchange',()=>{state=C.decode(location.search);state.compare=[...new Set(state.compare.map(id=>D.redirects[id]||id))].filter(id=>byId[id]);render();if(!routeName())window.scrollTo(0,listScroll);else if(location.hash.split('/').length<4)window.scrollTo(0,0);});
  window.addEventListener('popstate',()=>{state=C.decode(location.search);render();});
  window.addEventListener('storage',e=>{if(e.key==='embodied-atlas.personal.v1'){try{personal=C.importPersonal(JSON.parse(e.newValue||'{"schemaVersion":1,"papers":{}}'),papers.map(p=>p.id),D.redirects).data;render();}catch{notify('其他标签页的记录格式无效，未载入。');}}});
  render();
})();
